ms_offset = 7

dist_color = "#A726D2"
default_color = "#EEA12D"
simple_color = "#3498db"
super_color = "#65cc29"  # Added a color for simple

plot_configs = [
    {
        "ax_index": 0,
        "title": "SARSA Convergence on Super Hard",
        "data": [
            {"values": sarsa_default, "offset": sd_offset, "label": "Default", "color": default_color},
            {"values": sarsa_dist_penalty, "offset": sv_offset, "label": "Distance Penalty", "color": dist_color},
            {"values": sarsa_simple, "offset": sp_offset, "label": "Simple", "color": simple_color},
            {"values": sarsa_super, "offset": ss_offset, "label": "Super Simple", "color": super_color},
        ],
    },
    {
        "ax_index": 1,
        "title": "MC On-Policy Convergence on Large Grid",
        "data": [
            {"values": mc_default, "offset": md_offset, "label": "Default", "color": default_color},
            {"values": mc_dist_penalty, "offset": mv_offset, "label": "Distance Penalty", "color": dist_color},
            {"values": mc_simple, "offset": mp_offset, "label": "Simple", "color": simple_color},
            {"values": mc_super, "offset": ms_offset, "label": "Super Simple", "color": super_color},
        ],
    },
]

# Create figure and subplots
fig, axes = plt.subplots(1, len(plot_configs), figsize=(15, 6))

legend = True
# Loop through each subplot configuration
for config in plot_configs:
    ax = axes[config["ax_index"]]

    # Plot each line in the subplot
    for line in config["data"]:
        ax.plot(
            range(line["offset"], len(line["values"]) + line["offset"]),
            line["values"],
            label=line["label"],
            color=line["color"],
            linewidth=1,
        )

    # Set subplot properties
    ax.set_xlabel("Iteration", fontsize=18)
    ax.set_ylabel("Steps per Episode", fontsize=18)
    ax.set_title(config["title"], fontsize=20, pad=10)

    # Set tick font sizes
    ax.tick_params(axis="x", labelsize=16)
    ax.tick_params(axis="y", labelsize=16)

    # Legend
    if legend:
        ax.legend(fontsize=18)
    legend = False
    # Grid styling
    ax.grid(True, linestyle="--", alpha=1, which="both")

plt.tight_layout()
plt.savefig("visualizations/RLConvergenceExample.png", dpi=300, bbox_inches="tight")
plt.close(fig)